import React,{useEffect,useMemo,useState} from 'react';
import{createRoot}from'react-dom/client';
import{BookOpen,GraduationCap,LayoutDashboard,ClipboardList,RefreshCw,Bell,LogOut,Menu,Search,CheckCircle2,Clock3,AlertCircle,Plus,ArrowRight,Layers,Users,ShieldCheck,ChevronRight,CalendarDays,BookMarked}from'lucide-react';
import'./style.css';
const API=(import.meta.env.VITE_API_BASE_URL||'http://localhost:8080').replace(/\/$/,'');
async function request(path,{token,method='GET',body}={}){const r=await fetch(API+path,{method,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});let data;try{data=await r.json()}catch{data={message:r.statusText}}if(!r.ok)throw new Error(data.message||data.error||`Yêu cầu thất bại (${r.status})`);return data?.data!==undefined?data.data:data}
const unwrapList=x=>Array.isArray(x)?x:[]; const dateText=x=>x?new Date(x).toLocaleDateString('vi-VN'):'—';
function App(){const [session,setSession]=useState(()=>{try{return JSON.parse(localStorage.getItem('huflit-session')||'null')}catch{return null}});const [page,setPage]=useState('overview');const [collapsed,setCollapsed]=useState(false);const [toast,setToast]=useState('');const [busy,setBusy]=useState(false);const [records,setRecords]=useState([]),[curriculum,setCurriculum]=useState(null),[rules,setRules]=useState([]),[notifications,setNotifications]=useState([]);const [search,setSearch]=useState('');const [modal,setModal]=useState('');const [error,setError]=useState('');
const role=session?.user?.role;const student=role==='STUDENT';
function notify(s){setToast(s);setTimeout(()=>setToast(''),3500)}
function logout(){localStorage.removeItem('huflit-session');setSession(null);setPage('overview')}
async function load(){if(!session)return;setBusy(true);setError('');const token=session.token;const jobs=student?[
['records',()=>request('/api/v1/student/academic-records',{token})],['curriculum',()=>request('/api/v1/student/curriculum',{token})],['rules',()=>request('/api/v1/student/replacement-rules',{token})],['notifications',()=>request('/api/v1/student/notifications',{token})]
]:[['rules',()=>request('/api/v1/admin/replacement-rules',{token})],['notifications',()=>request('/api/v1/admin/notifications',{token})]];
const results=await Promise.all(jobs.map(async([k,fn])=>{try{return[k,await fn(),null]}catch(e){return[k,null,e.message]}}));for(const[k,v,e]of results){if(k==='records'&&v)setRecords(unwrapList(v));if(k==='curriculum'&&v)setCurriculum(v);if(k==='rules'&&v)setRules(unwrapList(v));if(k==='notifications'&&v)setNotifications(unwrapList(v));if(e&&!(e.includes('chưa được gán CTĐT')))setError(old=>old?old+` · ${e}`:e)}setBusy(false)}
useEffect(()=>{load()},[session]);
if(!session)return <Login onLogin={s=>{localStorage.setItem('huflit-session',JSON.stringify(s));setSession(s);setPage('overview')}}/>;
const nav=student?[['overview','Tổng quan',LayoutDashboard],['curriculum','CTĐT của tôi',BookOpen],['catalog','Tra cứu CTĐT',Search],['records','Kết quả học tập',ClipboardList],['rules','Môn học thay thế',RefreshCw],['notifications','Thông báo',Bell]]:[['overview','Tổng quan',LayoutDashboard],['majors','Ngành đào tạo',GraduationCap],['courses','Danh mục học phần',BookOpen],['curriculums','Quản lý CTĐT',Layers],['changes','Lịch sử thay đổi',Clock3],['records','Kết quả học tập',ClipboardList],['rules','Quy tắc thay thế',RefreshCw],['notifications','Thông báo',Bell]];
const unread=notifications.filter(n=>student && n.read !== true).length;
return <div className="app-shell"><aside className={`sidebar ${collapsed?'small':''}`}><div className="brand"><div className="brand-mark"><GraduationCap size={25}/></div>{!collapsed&&<div><b>HUFLIT</b><span>CURRICULUM PORTAL</span></div>}</div><div className="nav-label">KHÔNG GIAN LÀM VIỆC</div>{nav.map(([id,label,Icon])=><button key={id} className={`nav-item ${page===id?'active':''}`} onClick={()=>setPage(id)} title={label}><Icon size={19}/>{!collapsed&&<><span>{label}</span>{id==='notifications'&&unread>0&&<i className="count">{unread}</i>}</>}</button>)}<div className="sidebar-bottom"><div className="help-card"><ShieldCheck size={19}/>{!collapsed&&<div><b>Dữ liệu học tập</b><span>Được phân quyền bảo vệ</span></div>}</div><button className="nav-item" onClick={logout}><LogOut size={19}/>{!collapsed&&<span>Đăng xuất</span>}</button></div></aside><main className="main"><header className="topbar"><button className="icon-btn" onClick={()=>setCollapsed(!collapsed)}><Menu size={20}/></button><div className="crumb">Cổng thông tin <ChevronRight size={14}/><b>{nav.find(x=>x[0]===page)?.[1]||'Tổng quan'}</b></div><div className="top-actions"><button className="icon-btn" onClick={load} title="Tải lại dữ liệu"><RefreshCw size={18}/></button><div className="avatar">{(session.user.fullName||'U').split(' ').slice(-1)[0][0]}</div><div className="user-mini"><b>{session.user.fullName||session.user.email}</b><span>{student?'Sinh viên':'Quản trị giáo vụ'}</span></div></div></header><div className="content"><div className="page-heading"><div><div className="eyebrow">HUFLIT · HỆ THỐNG THEO DÕI CTĐT</div><h1>{nav.find(x=>x[0]===page)?.[1]||'Tổng quan'}</h1><p>{student?'Theo dõi chương trình đào tạo áp dụng và tiến độ học tập của bạn.':'Quản lý dữ liệu kết quả học tập, quy tắc thay thế và thông báo.'}</p></div><div className="heading-actions"><span className="role-chip"><ShieldCheck size={15}/>{role}</span></div></div>{error&&<div className="alert"><AlertCircle size={18}/><span>{error}</span><button onClick={()=>setError('')}>×</button></div>}{busy&&<div className="loading-line"><span/> Đang đồng bộ dữ liệu...</div>}
{page==='overview'&&<Overview student={student} curriculum={curriculum} records={records} rules={rules} notifications={notifications} go={setPage} />}
{page==='curriculum'&&<Curriculum data={curriculum} search={search} setSearch={setSearch}/>}{page==='catalog'&&<CurriculumCatalog token={session.token}/>}{['majors','courses','curriculums','changes'].includes(page)&&<AdminWorkspace kind={page} token={session.token} notify={notify}/>}
{page==='records'&&<Records student={student} records={records} search={search} setSearch={setSearch} token={session.token} onAdd={()=>setModal('attempt')} />}
{page==='rules'&&<Rules student={student} rules={rules} search={search} setSearch={setSearch} onAdd={()=>setModal('rule')} onEdit={r=>{setModal('rule');window.__ruleEdit=r}} token={session.token} refresh={load} notify={notify}/>}
{page==='notifications'&&<Notifications student={student} items={notifications} token={session.token} refresh={load} notify={notify} onAdd={()=>setModal('notification')}/>}
</div></main>{toast&&<div className="toast"><CheckCircle2 size={18}/>{toast}</div>}{modal==='attempt'&&<AttemptModal token={session.token} onClose={()=>setModal('')} onDone={()=>{setModal('');load();notify('Đã lưu kết quả học tập')}}/>}{modal==='rule'&&<RuleModal token={session.token} initial={window.__ruleEdit||null} onClose={()=>{setModal('');window.__ruleEdit=null}} onDone={()=>{setModal('');window.__ruleEdit=null;load();notify('Đã lưu quy tắc thay thế')}}/>}{modal==='notification'&&<NotificationModal token={session.token} onClose={()=>setModal('')} onDone={()=>{setModal('');load();notify('Đã tạo thông báo')}}/>}</div>}
function Login({onLogin}){const[email,setEmail]=useState('25001234@huflit.edu.vn'),[password,setPassword]=useState('123456'),[busy,setBusy]=useState(false),[err,setErr]=useState('');async function submit(e){e.preventDefault();setBusy(true);setErr('');try{const data=await request('/api/v1/auth/login',{method:'POST',body:{email,password}});if(!data?.token)throw new Error('API đăng nhập không trả về token.');onLogin({token:data.token,user:data})}catch(e){setErr(e.message+' — hãy kiểm tra backend tại '+API)}finally{setBusy(false)}}return <div className="login-layout"><div className="login-art"><div className="login-brand"><div className="brand-mark"><GraduationCap size={27}/></div><div><b>HUFLIT</b><span>CURRICULUM PORTAL</span></div></div><div className="art-copy"><span className="pill-light">CỔNG THÔNG TIN SINH VIÊN</span><h1>Hiểu lộ trình.<br/><em>Chủ động tương lai.</em></h1><p>Theo dõi chương trình đào tạo, kết quả học tập và những thay đổi học phần trên cùng một nền tảng.</p><div className="art-points"><span><CheckCircle2/> CTĐT áp dụng cá nhân</span><span><CheckCircle2/> Theo dõi tiến độ trực quan</span><span><CheckCircle2/> Cập nhật thay thế học phần</span></div></div><div className="art-footer">TRƯỜNG ĐẠI HỌC NGOẠI NGỮ - TIN HỌC TP. HỒ CHÍ MINH</div></div><div className="login-panel"><form className="login-form" onSubmit={submit}><div className="eyebrow">CHÀO MỪNG BẠN QUAY LẠI</div><h2>Đăng nhập</h2><p className="muted">Sử dụng tài khoản HUFLIT để tiếp tục.</p>{err&&<div className="alert"><AlertCircle size={17}/>{err}</div>}<label>Email trường</label><input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="mssv@huflit.edu.vn" required/><label>Mật khẩu</label><input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Nhập mật khẩu" required/><button className="primary full" disabled={busy}>{busy?'Đang đăng nhập...':'Đăng nhập'} <ArrowRight size={17}/></button><div className="login-hint"><ShieldCheck size={17}/> Xác thực bảo mật bằng JWT</div><div className="demo-note"><b>Tài khoản demo seed</b><span>Sinh viên: 25001234@huflit.edu.vn</span><span>Mật khẩu mặc định: 123456</span></div></form></div></div>}
function Overview({student,curriculum,records,rules,notifications,go}){const passed=records.filter(r=>r.status==='PASSED').length;const failed=records.filter(r=>r.status==='FAILED').length;const unread=notifications.filter(n=>n.read !== true).length;return <><div className="welcome-banner"><div><span className="banner-tag">{student?'HỌC TẬP CỦA BẠN':'QUẢN TRỊ HỆ THỐNG'}</span><h2>{student?'Chào bạn, '+(JSON.parse(localStorage.getItem('huflit-session')||'{}').user?.fullName||'sinh viên'):'Trung tâm quản lý chương trình đào tạo'}</h2><p>{student?'Mọi thông tin về CTĐT và kết quả học tập được tổng hợp tại đây.':'Theo dõi và cập nhật dữ liệu đào tạo theo đúng phân quyền nghiệp vụ.'}</p></div><div className="banner-icon"><GraduationCap size={60}/></div></div><div className="stats-grid">{(student?[{label:'Học phần đã ghi nhận',value:records.length,sub:'Có dữ liệu kết quả',icon:BookMarked},{label:'Đã hoàn thành',value:passed,sub:'Trạng thái đạt',icon:CheckCircle2},{label:'Chưa đạt',value:failed,sub:'Cần theo dõi',icon:Clock3},{label:'Thông báo',value:notifications.length,sub:'Cập nhật hệ thống',icon:Bell}]:[{label:'Sinh viên có dữ liệu',value:'—',sub:'Theo mã sinh viên',icon:Users},{label:'Quy tắc thay thế',value:rules.length,sub:'Đang được quản lý',icon:RefreshCw},{label:'Thông báo',value:notifications.length,sub:'Trong hệ thống',icon:Bell},{label:'Kết quả học tập',value:'Quản lý',sub:'Cập nhật bởi giáo vụ',icon:ClipboardList}]).map((s,i)=><div className="stat-card" key={s.label}><div className={`stat-icon tone-${i}`}><s.icon size={20}/></div><span>{s.label}</span><strong>{s.value}</strong><small>{s.sub}</small></div>)}</div><div className="dashboard-grid"><section className="panel wide"><div className="panel-head"><div><h3>{student?'Tóm tắt tiến độ CTĐT':'Tác vụ quản lý'}</h3><p>{student?'Thông tin dựa trên dữ liệu đã đồng bộ từ hệ thống.':'Đi nhanh đến các nghiệp vụ thường dùng.'}</p></div><button className="text-btn" onClick={()=>go(student?'curriculum':'records')}>Xem chi tiết <ArrowRight size={15}/></button></div>{student?<><div className="progress-summary"><div className="progress-ring"><strong>{curriculum?.completionPercent??0}%</strong></div><div className="progress-copy"><b>{curriculum?.curriculumName||'Chưa tải được chương trình đào tạo'}</b><span>{curriculum?.curriculumCode||'Kiểm tra CTĐT được gán cho tài khoản'}</span><div className="progress-track"><i style={{width:`${Math.min(100,Math.max(0,curriculum?.completionPercent||0))}%`}}/></div><small>{curriculum?.passedCourses||0} / {curriculum?.totalCourses||0} học phần hoàn thành</small></div></div><button className="outline wide-btn" onClick={()=>go('curriculum')}>Xem chương trình đào tạo <ArrowRight size={16}/></button></>:<div className="quick-actions"><button onClick={()=>go('records')}><ClipboardList/><b>Quản lý kết quả</b><span>Tra cứu và ghi nhận lần học</span></button><button onClick={()=>go('rules')}><RefreshCw/><b>Quy tắc thay thế</b><span>Quản lý môn cũ và môn mới</span></button><button onClick={()=>go('notifications')}><Bell/><b>Thông báo</b><span>Gửi thông tin đến sinh viên</span></button></div>}</section><section className="panel"><div className="panel-head"><div><h3>{student?'Thông báo gần đây':'Lưu ý nghiệp vụ'}</h3><p>{student?'Cập nhật mới nhất':'Nguyên tắc dữ liệu'}</p></div></div>{student?(notifications.slice(0,4).map((n,i)=><div className="mini-notice" key={n.id||i}><span className="notice-dot"/><div><b>{n.title||'Thông báo'}</b><small>{dateText(n.createdAt)}</small></div></div>)): <div className="principles"><div><CheckCircle2/><span>Điểm cao nhất qua các lần học được dùng để xác định kết quả.</span></div><div><CheckCircle2/><span>Quy tắc thay thế áp dụng theo CTĐT/khóa, không tự đăng ký môn.</span></div><div><CheckCircle2/><span>Chỉ tài khoản Admin được cập nhật dữ liệu nghiệp vụ.</span></div></div>}<button className="text-btn bottom-link" onClick={()=>go(student?'notifications':'rules')}>Mở {student?'thông báo':'quản lý quy tắc'} <ArrowRight size={15}/></button></section></div></>}
function SearchBar({value,onChange,placeholder='Tìm theo mã hoặc tên...'}){return <div className="searchbox"><Search size={17}/><input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/></div>}
function Curriculum({data,search,setSearch}){if(!data)return <Empty title="Chưa có dữ liệu CTĐT" text="Tài khoản có thể chưa được gán chương trình đào tạo hoặc API chưa trả dữ liệu."/>;const semesters=data.semesters||[];const visible=semesters.map(s=>({...s,courses:(s.courses||[]).filter(c=>(c.courseCode+' '+(c.courseName||'')).toLowerCase().includes(search.toLowerCase()))})).filter(s=>s.courses.length);return <><div className="curriculum-summary panel"><div className="curriculum-icon"><Layers size={27}/></div><div className="curriculum-info"><span className="eyebrow">CHƯƠNG TRÌNH ĐANG ÁP DỤNG</span><h2>{data.curriculumName}</h2><p>{data.curriculumCode} · {data.cohort} · Phiên bản {data.version}</p></div><div className="summary-percent"><strong>{data.completionPercent??0}%</strong><span>hoàn thành</span></div></div><div className="toolbar"><SearchBar value={search} onChange={setSearch} placeholder="Tìm học phần, mã môn..."/><span className="muted">{data.passedCourses||0}/{data.totalCourses||0} học phần đạt · {data.passedCredits||0} tín chỉ tích lũy</span></div>{(data.knowledgeGroupProgress||[]).length>0&&<div className="group-progress-grid">{data.knowledgeGroupProgress.map(g=><div className="group-progress-card" key={g.knowledgeGroupCode}><div><b>{g.knowledgeGroupCode==='UNASSIGNED'?'Chưa phân nhóm':g.knowledgeGroupCode}</b><span>{g.passedCourses||0}/{g.totalCourses||0} học phần đạt</span></div><div className="progress-track"><i style={{width:`${g.totalCourses?Math.min(100,(g.passedCourses||0)*100/g.totalCourses):0}%`}}/></div><small>{g.passedCredits||0}/{g.totalCredits||0} tín chỉ</small></div>)}</div>}{visible.length?visible.map(s=><section className="panel semester-panel" key={s.semesterNumber}><div className="semester-heading"><div className="semester-num">HK {s.semesterNumber}</div><div><h3>Học kỳ {s.semesterNumber}</h3><span>{s.courses.length} học phần trong CTĐT</span></div></div><div className="table-wrap"><table><thead><tr><th>Mã học phần</th><th>Tên học phần</th><th>Tín chỉ</th><th>Loại</th><th>Điểm cao nhất</th><th>Trạng thái</th></tr></thead><tbody>{s.courses.map(c=><tr key={c.courseCode}><td className="code-cell">{c.courseCode}</td><td><b>{c.courseName||'Chưa có tên học phần'}</b>{c.prerequisiteCourseCodes?.length>0&&<small className="subline">Tiên quyết: {c.prerequisiteCourseCodes.join(', ')}</small>}{c.prerequisitesSatisfied===false&&<small className="subline prerequisite-warning">Chưa đủ điều kiện: {(c.missingPrerequisiteCourseCodes||[]).join(', ')}</small>}</td><td>{c.credits}</td><td><span className="type-pill">{c.type==='MANDATORY'?'Bắt buộc':'Tự chọn'}</span></td><td>{c.highestScore10??'—'}</td><td><Status value={c.status}/></td></tr>)}</tbody></table></div></section>):<Empty title="Không tìm thấy học phần" text="Thử từ khóa khác."/>}</>}
function Records({student,records,search,setSearch,onAdd,token}){const [studentId,setStudentId]=useState(''),[loadedRecords,setLoadedRecords]=useState([]),[lookupBusy,setLookupBusy]=useState(false),[lookupError,setLookupError]=useState('');const sourceRecords=student?records:loadedRecords;const filtered=sourceRecords.filter(r=>(r.courseCode||'').toLowerCase().includes(search.toLowerCase()));async function lookupStudent(e){e.preventDefault();setLookupBusy(true);setLookupError('');try{const data=await request(`/api/v1/admin/academic-records/student/${encodeURIComponent(studentId.trim())}`,{token});setLoadedRecords(unwrapList(data));}catch(err){setLookupError(err.message);setLoadedRecords([])}finally{setLookupBusy(false)}}return <>{!student&&<form className="toolbar lookup-toolbar" onSubmit={lookupStudent}><SearchBar value={studentId} onChange={setStudentId} placeholder="Nhập MongoDB ID sinh viên..."/><button className="primary" disabled={lookupBusy||!studentId.trim()}>{lookupBusy?'Đang tìm...':'Tra cứu sinh viên'}</button><button type="button" className="outline" onClick={onAdd}><Plus size={17}/> Ghi nhận kết quả</button></form>}{lookupError&&<div className="alert">{lookupError}</div>}<div className="toolbar"><SearchBar value={search} onChange={setSearch} placeholder="Tìm theo mã học phần..."/>{!student&&<span className="muted">{studentId?'Đang xem kết quả của sinh viên đã tra cứu.':'Cần tra cứu sinh viên bằng MongoDB ID.'}</span>}</div><div className="panel table-panel"><div className="panel-head"><div><h3>{student?'Lịch sử kết quả học tập':'Danh sách kết quả học tập'}</h3><p>{student?'Điểm cao nhất được dùng để xác định trạng thái đạt.':'Ghi nhận kết quả học tập do giáo vụ xác minh.'}</p></div><span className="neutral-chip">{filtered.length} bản ghi</span></div>{filtered.length?<div className="table-wrap"><table><thead><tr>{!student&&<th>Mã sinh viên</th>}<th>Mã học phần</th><th>Số lần học</th><th>Điểm hệ 10</th><th>Điểm chữ</th><th>Hệ 4</th><th>Trạng thái</th></tr></thead><tbody>{filtered.map((r,i)=><tr key={r.id||r.courseCode||i}>{!student&&<td className="code-cell">{r.studentId||'—'}</td>}<td className="code-cell">{r.courseCode}</td><td>{r.attempts?.length||0}</td><td><b>{r.highestScore10??'—'}</b></td><td>{r.highestLetterGrade||'—'}</td><td>{r.highestScore4??'—'}</td><td><Status value={r.status}/></td></tr>)}</tbody></table></div>:<Empty title="Chưa có kết quả học tập" text={student?'Khi dữ liệu kết quả được cập nhật, thông tin sẽ hiển thị tại đây.':studentId?'Sinh viên chưa có kết quả hoặc không có bản ghi phù hợp.':'Tra cứu sinh viên trước để xem kết quả học tập.'}/>}</div><div className="info-strip"><AlertCircle size={18}/><span>Kết quả học phần sử dụng điểm cao nhất trong các lần học. Sinh viên chỉ xem kết quả; thao tác ghi nhận do tài khoản giáo vụ thực hiện.</span></div></>}
function Rules({student,rules,search,setSearch,onAdd,onEdit,token,refresh,notify}){const filtered=rules.filter(r=>JSON.stringify([r.oldCourseCodes,r.newCourseCodes,r.reason,r.ruleType,r.applicableCohorts]).toLowerCase().includes(search.toLowerCase()));return <><div className="toolbar"><SearchBar value={search} onChange={setSearch} placeholder="Tìm mã môn, khóa, lý do..."/>{!student&&<button className="primary" onClick={onAdd}><Plus size={17}/> Tạo quy tắc</button>}</div><div className="rule-grid">{filtered.map((r,i)=><article className="rule-card" key={r.id||i}><div className="rule-top"><span className="rule-type">{r.ruleType||'Thay thế học phần'}</span><Status value={r.status}/></div><div className="course-swap"><div><small>HỌC PHẦN CŨ</small><b>{(r.oldCourseCodes||[]).join(', ')||'—'}</b></div><ArrowRight size={19}/><div><small>HỌC PHẦN MỚI</small><b>{(r.newCourseCodes||[]).join(', ')||'—'}</b></div></div><p className="rule-reason">{r.reason||'Chưa có lý do được cung cấp.'}</p><div className="rule-meta"><span><GraduationCap size={15}/> {(r.applicableCohorts||[]).join(', ')||'Mọi khóa được cấu hình'}</span><span><CalendarDays size={15}/> {dateText(r.effectiveDate)}</span></div>{r.note&&<p className="rule-note">{r.note}</p>}{!student&&<button className="outline full" onClick={()=>onEdit(r)}>Chỉnh sửa quy tắc</button>}</article>)}{!filtered.length&&<Empty title="Chưa có quy tắc thay thế" text={student?'Hiện chưa có quy tắc áp dụng cho CTĐT/khóa của bạn.':'Tạo quy tắc để quản lý học phần thay thế.'}/>}</div><div className="info-strip"><AlertCircle size={18}/><span>Quy tắc thay thế chỉ thể hiện quan hệ giữa học phần theo chương trình/khóa. Hệ thống không tự đăng ký học phần mới thay sinh viên.</span></div></>}
function Notifications({student,items,token,refresh,notify,onAdd}){async function read(n){try{const isRead=n.read===true;await request(`/api/v1/student/notifications/${n.id}/${isRead?'unread':'read'}`,{token,method:'PATCH'});notify(isRead?'Đã đánh dấu chưa đọc':'Đã đánh dấu đã đọc');refresh()}catch(e){notify(e.message)}}return <><div className="toolbar"><span className="muted">{items.length} thông báo trong danh sách</span>{!student&&<button className="primary" onClick={onAdd}><Plus size={17}/> Tạo thông báo</button>}</div><div className="panel notice-list">{items.map((n,i)=>{const isRead=student ? n.read === true : false;return <article className="notice-row" key={n.id||i}><div className="notice-icon"><Bell size={19}/></div><div className="notice-body"><div className="notice-title"><b>{n.title||'Thông báo'}</b>{student&&!isRead&&<span className="unread-pill">Mới</span>}</div><p>{n.message||'Không có nội dung.'}</p><div className="notice-meta"><span>{n.type||'GENERAL'}</span><span>{dateText(n.createdAt)}</span>{n.courseCode&&<span>Học phần {n.courseCode}</span>}</div></div>{student&&<button className="outline read-btn" onClick={()=>read(n)}>{isRead?'Đánh dấu chưa đọc':'Đánh dấu đã đọc'}</button>}</article>})}{!items.length&&<Empty title="Chưa có thông báo" text="Các thông báo mới sẽ xuất hiện tại đây."/>}</div></>}
function Status({value}){const v=String(value||'NOT_STUDIED').toUpperCase();const cls=v==='PASSED'||v==='ACTIVE'?'good':v==='FAILED'||v==='INACTIVE'?'bad':v==='DRAFT'?'warn':'muted-status';const label={PASSED:'Đạt',FAILED:'Chưa đạt',NOT_STUDIED:'Chưa học',ACTIVE:'Đang áp dụng',INACTIVE:'Ngừng áp dụng',DRAFT:'Bản nháp'}[v]||v;return <span className={`status ${cls}`}><i/>{label}</span>}
function Empty({title,text}){return <div className="empty"><div className="empty-icon"><BookOpen size={24}/></div><b>{title}</b><p>{text}</p></div>}
function Modal({title,children,onClose,onSubmit,busy}){return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><form className="modal" onSubmit={onSubmit}><div className="modal-head"><div><span className="eyebrow">HUFLIT · QUẢN TRỊ DỮ LIỆU</span><h2>{title}</h2></div><button type="button" className="icon-btn" onClick={onClose}>×</button></div>{children}<div className="modal-actions"><button type="button" className="outline" onClick={onClose}>Hủy</button><button className="primary" disabled={busy}>{busy?'Đang lưu...':'Lưu dữ liệu'}</button></div></form></div>}
function AttemptModal({token,onClose,onDone}){const[studentId,setStudentId]=useState(''),[curriculumId,setCurriculumId]=useState(''),[courseCode,setCourseCode]=useState(''),[semesterCode,setSemesterCode]=useState(''),[score,setScore]=useState(''),[busy,setBusy]=useState(false),[err,setErr]=useState('');async function submit(e){e.preventDefault();setBusy(true);setErr('');try{await request('/api/v1/admin/academic-records/attempts',{token,method:'POST',body:{studentId,curriculumId,courseCode,attempt:{semesterCode,score10:Number(score)}}});onDone()}catch(e){setErr(e.message)}finally{setBusy(false)}}return <Modal title="Ghi nhận kết quả học tập" onClose={onClose} onSubmit={submit} busy={busy}>{err&&<div className="alert">{err}</div>}<div className="form-grid"><Field label="MongoDB ID sinh viên" value={studentId} set={setStudentId} required/><Field label="MongoDB ID CTĐT" value={curriculumId} set={setCurriculumId} required/><Field label="Mã học phần" value={courseCode} set={setCourseCode} required/><Field label="Học kỳ / kỳ học" value={semesterCode} set={setSemesterCode} required/><Field label="Điểm hệ 10 (0–10)" value={score} set={setScore} type="number" min="0" max="10" step="0.1" required/></div><p className="field-hint">Điểm chữ, hệ 4 và trạng thái sẽ được backend tính theo quy tắc quy đổi.</p></Modal>}
function Field({label,value,set,type='text',...props}){return <label className="field-label">{label}<input type={type} value={value} onChange={e=>set(e.target.value)} {...props}/></label>}
function RuleModal({token,initial,onClose,onDone}){const[rType,setRType]=useState(initial?.ruleType||'1-1'),[old,setOld]=useState((initial?.oldCourseCodes||[]).join(', ')),[fresh,setFresh]=useState((initial?.newCourseCodes||[]).join(', ')),[major,setMajor]=useState(initial?.majorId||''),[cohorts,setCohorts]=useState((initial?.applicableCohorts||[]).join(', ')),[effective,setEffective]=useState(initial?.effectiveDate?String(initial.effectiveDate).slice(0,10):''),[reason,setReason]=useState(initial?.reason||''),[note,setNote]=useState(initial?.note||''),[status,setStatus]=useState(initial?.status||'ACTIVE'),[busy,setBusy]=useState(false),[err,setErr]=useState('');async function submit(e){e.preventDefault();setBusy(true);setErr('');const body={ruleType:rType,oldCourseCodes:old.split(',').map(x=>x.trim()).filter(Boolean),newCourseCodes:fresh.split(',').map(x=>x.trim()).filter(Boolean),majorId:major||null,applicableCohorts:cohorts.split(',').map(x=>x.trim()).filter(Boolean),effectiveDate:effective||null,reason,note,status};try{await request(initial?.id?`/api/v1/admin/replacement-rules/${initial.id}`:'/api/v1/admin/replacement-rules',{token,method:initial?.id?'PUT':'POST',body});onDone()}catch(e){setErr(e.message)}finally{setBusy(false)}}return <Modal title={initial?'Chỉnh sửa quy tắc':'Tạo quy tắc thay thế'} onClose={onClose} onSubmit={submit} busy={busy}>{err&&<div className="alert">{err}</div>}<div className="form-grid"><label className="field-label">Loại quy tắc<select value={rType} onChange={e=>setRType(e.target.value)}><option>1-1</option><option>1-N</option><option>N-1</option></select></label><Field label="Mã học phần cũ (phân cách dấu phẩy)" value={old} set={setOld} required/><Field label="Mã học phần mới (phân cách dấu phẩy)" value={fresh} set={setFresh} required/><Field label="Major ID (ObjectId)" value={major} set={setMajor}/><Field label="Khóa áp dụng (vd K2025, K2026)" value={cohorts} set={setCohorts} required/><Field label="Ngày hiệu lực" value={effective} set={setEffective} type="date"/><Field label="Lý do" value={reason} set={setReason} required/><label className="field-label">Trạng thái<select value={status} onChange={e=>setStatus(e.target.value)}><option>ACTIVE</option><option>INACTIVE</option></select></label><label className="field-label full-field">Ghi chú<textarea value={note} onChange={e=>setNote(e.target.value)} rows="3"/></label></div></Modal>}
function NotificationModal({token,onClose,onDone}){const[title,setTitle]=useState(''),[message,setMessage]=useState(''),[type,setType]=useState('CURRICULUM_CHANGE'),[curriculumId,setCurriculumId]=useState(''),[courseCode,setCourseCode]=useState(''),[replacementRuleId,setReplacementRuleId]=useState(''),[recipientIds,setRecipientIds]=useState(''),[busy,setBusy]=useState(false),[err,setErr]=useState('');async function submit(e){e.preventDefault();setBusy(true);setErr('');try{await request('/api/v1/admin/notifications',{token,method:'POST',body:{title,message,type,curriculumId:curriculumId||null,courseCode:courseCode||null,replacementRuleId:replacementRuleId||null,recipientIds:recipientIds.split(',').map(x=>x.trim()).filter(Boolean)}});onDone()}catch(e){setErr(e.message)}finally{setBusy(false)}}return <Modal title="Tạo thông báo" onClose={onClose} onSubmit={submit} busy={busy}>{err&&<div className="alert">{err}</div>}<div className="form-grid"><Field label="Tiêu đề" value={title} set={setTitle} required/><label className="field-label">Loại thông báo<select value={type} onChange={e=>setType(e.target.value)}><option>CURRICULUM_CHANGE</option><option>COURSE_REPLACEMENT</option></select></label><label className="field-label full-field">Nội dung<textarea value={message} onChange={e=>setMessage(e.target.value)} rows="4" required/></label><Field label="CTĐT ID (nếu có)" value={curriculumId} set={setCurriculumId}/><Field label="Mã học phần (nếu có)" value={courseCode} set={setCourseCode}/><Field label="Replacement Rule ID (nếu có)" value={replacementRuleId} set={setReplacementRuleId}/><label className="field-label full-field">Danh sách recipient ObjectId (phân cách dấu phẩy)<input value={recipientIds} onChange={e=>setRecipientIds(e.target.value)} placeholder="Để trống nếu logic backend cho phép"/></label></div><p className="field-hint">Chỉ nhập ID sinh viên đã tồn tại trong MongoDB. Việc gửi thông báo không đăng ký học phần thay cho sinh viên.</p></Modal>}

function CurriculumCatalog({token}){
 const [items,setItems]=useState([]),[search,setSearch]=useState(''),[loading,setLoading]=useState(false),[error,setError]=useState(''),[selected,setSelected]=useState(null);
 async function load(){setLoading(true);setError('');try{const data=await request(`/api/curriculums?keyword=${encodeURIComponent(search)}`,{token});setItems(unwrapList(data));}catch(e){setError(e.message)}finally{setLoading(false)}}
 useEffect(()=>{load()},[]);
 const filtered=items.filter(c=>JSON.stringify([c.curriculumCode,c.curriculumName,c.cohort,c.status]).toLowerCase().includes(search.toLowerCase()));
 async function detail(c){setError('');try{setSelected(await request(`/api/curriculums/${c.id}`,{token}))}catch(e){setError(e.message)}}
 return <><div className="toolbar"><SearchBar value={search} onChange={setSearch} placeholder="Tìm CTĐT theo mã, tên, khóa..."/><button className="primary" onClick={load} disabled={loading}>{loading?'Đang tải...':'Tìm kiếm'}</button></div>{error&&<div className="alert">{error}</div>}{selected&&<section className="panel catalog-detail"><div className="panel-head"><div><span className="eyebrow">CHI TIẾT CHƯƠNG TRÌNH</span><h3>{selected.curriculumName}</h3><p>{selected.curriculumCode} · {selected.cohort} · Phiên bản {selected.version}</p></div><button className="outline" onClick={()=>setSelected(null)}>Đóng chi tiết</button></div>{(selected.semesters||[]).map(sem=><div className="catalog-semester" key={sem.semesterNumber}><b>Học kỳ {sem.semesterNumber}</b><div className="table-wrap"><table><thead><tr><th>Mã môn</th><th>Tên học phần</th><th>Tín chỉ</th><th>Loại</th><th>Tiên quyết</th></tr></thead><tbody>{(sem.courses||[]).map(c=><tr key={c.courseCode}><td className="code-cell">{c.courseCode}</td><td>{c.courseName||'—'}</td><td>{c.credits??'—'}</td><td>{c.type==='MANDATORY'?'Bắt buộc':'Tự chọn'}</td><td>{(c.prerequisiteCourseCodes||[]).join(', ')||'—'}</td></tr>)}</tbody></table></div></div>)}</section>}<div className="panel table-panel"><div className="panel-head"><div><h3>Danh sách chương trình đào tạo</h3><p>Tra cứu CTĐT theo mã, tên, khóa tuyển sinh hoặc trạng thái.</p></div><span className="neutral-chip">{filtered.length} CTĐT</span></div>{filtered.length?<div className="table-wrap"><table><thead><tr><th>Mã CTĐT</th><th>Tên chương trình</th><th>Khóa</th><th>Năm áp dụng</th><th>Phiên bản</th><th>Trạng thái</th><th></th></tr></thead><tbody>{filtered.map(c=><tr key={c.id}><td className="code-cell">{c.curriculumCode}</td><td><b>{c.curriculumName}</b></td><td>{c.cohort||'—'}</td><td>{c.appliedYear||'—'}</td><td>{c.version||1}</td><td><Status value={c.status}/></td><td><button className="text-btn" onClick={()=>detail(c)}>Xem chi tiết <ArrowRight size={14}/></button></td></tr>)}</tbody></table></div>:<Empty title="Không tìm thấy CTĐT" text="Thử từ khóa khác hoặc kiểm tra dữ liệu chương trình."/>}</div></>
}
function AdminWorkspace({kind,token,notify}){
 const [items,setItems]=useState([]),[majors,setMajors]=useState([]),[search,setSearch]=useState(''),[loading,setLoading]=useState(false),[error,setError]=useState(''),[modal,setModal]=useState(false),[editing,setEditing]=useState(null),[detail,setDetail]=useState(null),[form,setForm]=useState({});
 const config={majors:{title:'Quản lý ngành đào tạo',base:'/api/majors'},courses:{title:'Danh mục học phần',base:'/api/courses'},curriculums:{title:'Quản lý chương trình đào tạo',base:'/api/curriculums'},changes:{title:'Lịch sử thay đổi',base:'/api/v1/admin/change-logs'}}[kind];
 async function load(){setLoading(true);setError('');try{let url=config.base;if(kind==='changes')url+=`?entityType=${encodeURIComponent(form.entityType||'')}`;else url+=`?keyword=${encodeURIComponent(search)}`;const data=await request(url,{token});setItems(unwrapList(data));if(kind==='curriculums'){const m=await request('/api/majors?status=ACTIVE',{token});setMajors(unwrapList(m))}}catch(e){setError(e.message)}finally{setLoading(false)}}
 useEffect(()=>{load()},[kind]);
 function openCreate(){setEditing(null);setDetail(null);setForm(kind==='majors'?{code:'',name:'',description:'',status:'ACTIVE'}:kind==='courses'?{courseCode:'',courseName:'',credits:3,theoryHours:30,practiceHours:0,department:'',description:'',status:'ACTIVE'}:{curriculumCode:'',curriculumName:'',majorId:'',cohort:'K2026',appliedYear:new Date().getFullYear(),description:'',status:'DRAFT',specializationSelectionTiming:'LATER',specializationSelectionSemester:5});setModal(true)}
 function openEdit(item){setEditing(item);setDetail(null);setForm(kind==='majors'?{name:item.name||'',description:item.description||'',status:item.status||'ACTIVE'}:kind==='courses'?{courseName:item.courseName||'',credits:item.credits??3,theoryHours:item.theoryHours??0,practiceHours:item.practiceHours??0,department:item.department||'',description:item.description||'',status:item.status||'ACTIVE'}:{curriculumName:item.curriculumName||'',majorId:item.majorId||'',cohort:item.cohort||'',appliedYear:item.appliedYear||new Date().getFullYear(),totalCredits:item.totalCredits??0,description:item.description||'',status:item.status||'DRAFT',specializationSelectionTiming:item.specializationSelectionTiming||'LATER',specializationSelectionSemester:item.specializationSelectionSemester??5,specializations:item.specializations||[],knowledgeGroups:item.knowledgeGroups||[],semesters:item.semesters||[]});setModal(true)}
 async function save(e){e.preventDefault();setError('');try{const body={...form};if(kind==='courses'){body.credits=Number(body.credits);body.theoryHours=Number(body.theoryHours);body.practiceHours=Number(body.practiceHours)}if(kind==='curriculums'){body.appliedYear=Number(body.appliedYear);body.totalCredits=Number(body.totalCredits||0);if(body.specializationSelectionTiming==='EARLY')body.specializationSelectionSemester=null;else body.specializationSelectionSemester=Number(body.specializationSelectionSemester||5);if(!editing){body.specializations=[];body.knowledgeGroups=[];body.semesters=[]}}const url=editing?`${config.base}/${editing.id}`:config.base;await request(url,{token,method:editing?'PUT':'POST',body});setModal(false);await load();notify(editing?'Đã cập nhật dữ liệu':'Đã tạo dữ liệu')}catch(e){setError(e.message)}}
 async function remove(item){if(!window.confirm(`Xác nhận chuyển trạng thái/xóa mềm ${item.name||item.courseName||item.curriculumName||item.code||item.courseCode||item.curriculumCode}?`))return;try{await request(`${config.base}/${item.id}`,{token,method:'DELETE'});await load();notify('Đã cập nhật trạng thái dữ liệu')}catch(e){setError(e.message)}}
 async function clone(item){const code=window.prompt('Mã CTĐT mới:');if(!code?.trim())return;const name=window.prompt('Tên CTĐT mới:',`${item.curriculumName} - bản sao`);if(!name?.trim())return;const cohort=window.prompt('Khóa áp dụng mới:',item.cohort||'K2026');if(!cohort?.trim())return;const year=Number(window.prompt('Năm áp dụng mới:',String(new Date().getFullYear())));if(!Number.isInteger(year)||year<2000){setError('Năm áp dụng không hợp lệ');return}try{await request(`/api/curriculums/${item.id}/clone`,{token,method:'POST',body:{newCurriculumCode:code.trim(),newCurriculumName:name.trim(),newCohort:cohort.trim(),newAppliedYear:year,status:'DRAFT'}});await load();notify('Đã sao chép CTĐT')}catch(e){setError(e.message)}}
 async function showDetail(item){setError('');try{const data=await request(`${config.base}/${item.id}`,{token});setDetail(data)}catch(e){setError(e.message)}}
 async function refreshDetail(){if(!detail?.id)return;try{const data=await request(`${config.base}/${detail.id}`,{token});setDetail(data);await load()}catch(e){setError(e.message)}}
 async function addKnowledgeGroup(){const groupCode=window.prompt('Mã nhóm kiến thức (vd: CS):');if(!groupCode?.trim())return;const groupName=window.prompt('Tên nhóm kiến thức:');if(!groupName?.trim())return;const order=Number(window.prompt('Thứ tự hiển thị:',String((detail.knowledgeGroups||[]).length+1)));try{await request(`/api/curriculums/${detail.id}/knowledge-groups`,{token,method:'POST',body:{groupCode:groupCode.trim(),groupName:groupName.trim(),order:Number.isFinite(order)?order:1}});await refreshDetail();notify('Đã thêm nhóm kiến thức')}catch(e){setError(e.message)}}
 async function addSpecialization(){const code=window.prompt('Mã chuyên ngành/định hướng:');if(!code?.trim())return;const name=window.prompt('Tên chuyên ngành/định hướng:');if(!name?.trim())return;try{await request(`/api/curriculums/${detail.id}/specializations`,{token,method:'POST',body:{code:code.trim(),name:name.trim()}});await refreshDetail();notify('Đã thêm chuyên ngành/định hướng')}catch(e){setError(e.message)}}
 async function editKnowledgeGroup(group){const groupName=window.prompt('Tên nhóm kiến thức:',group.groupName||'');if(!groupName?.trim())return;const order=Number(window.prompt('Thứ tự hiển thị:',String(group.order||1)));try{await request(`/api/curriculums/${detail.id}/knowledge-groups/${encodeURIComponent(group.groupCode)}`,{token,method:'PUT',body:{groupName:groupName.trim(),order:Number.isFinite(order)?order:1}});await refreshDetail();notify('Đã cập nhật nhóm kiến thức')}catch(e){setError(e.message)}}
 async function removeKnowledgeGroup(group){if(!window.confirm(`Xóa nhóm kiến thức ${group.groupCode}? Nhóm đang được học phần sử dụng sẽ không thể xóa.`))return;try{await request(`/api/curriculums/${detail.id}/knowledge-groups/${encodeURIComponent(group.groupCode)}`,{token,method:'DELETE'});await refreshDetail();notify('Đã xóa nhóm kiến thức')}catch(e){setError(e.message)}}
 async function removeSpecialization(spec){if(!window.confirm(`Xóa định hướng ${spec.code}?`))return;try{await request(`/api/curriculums/${detail.id}/specializations/${encodeURIComponent(spec.code)}`,{token,method:'DELETE'});await refreshDetail();notify('Đã xóa định hướng')}catch(e){setError(e.message)}}
 async function addCurriculumCourse(){const courseCode=window.prompt('Mã học phần trong danh mục:');if(!courseCode?.trim())return;const semesterNumber=Number(window.prompt('Học kỳ:', '1'));if(!Number.isInteger(semesterNumber)||semesterNumber<1){setError('Học kỳ phải là số nguyên lớn hơn 0');return}const type=window.prompt('Loại học phần: MANDATORY hoặc ELECTIVE','MANDATORY');if(!['MANDATORY','ELECTIVE'].includes(String(type||'').toUpperCase())){setError('Loại học phần chỉ nhận MANDATORY hoặc ELECTIVE');return}const knowledgeGroupCode=window.prompt('Mã nhóm kiến thức (bỏ trống nếu chưa gán):','')||null;const prerequisites=(window.prompt('Mã học phần tiên quyết, phân cách dấu phẩy (có thể bỏ trống):','')||'').split(',').map(x=>x.trim()).filter(Boolean);const specializationCodes=(window.prompt('Mã định hướng áp dụng, phân cách dấu phẩy (có thể bỏ trống):','')||'').split(',').map(x=>x.trim()).filter(Boolean);try{await request(`/api/curriculums/${detail.id}/courses`,{token,method:'POST',body:{courseCode:courseCode.trim(),semesterNumber,type:String(type).toUpperCase(),knowledgeGroupCode,specializationCodes,prerequisiteCourseCodes:prerequisites}});await refreshDetail();notify('Đã thêm học phần vào CTĐT')}catch(e){setError(e.message)}}
 async function removeCurriculumCourse(courseCode){if(!window.confirm(`Xóa học phần ${courseCode} khỏi CTĐT?`))return;try{await request(`/api/curriculums/${detail.id}/courses/${encodeURIComponent(courseCode)}`,{token,method:'DELETE'});await refreshDetail();notify('Đã xóa học phần khỏi CTĐT')}catch(e){setError(e.message)}}
 async function editCurriculumCourse(course,semesterNumber){const sem=Number(window.prompt('Học kỳ mới:',String(semesterNumber)));if(!Number.isInteger(sem)||sem<1)return;const type=String(window.prompt('Loại: MANDATORY hoặc ELECTIVE',course.type||'MANDATORY')||course.type).toUpperCase();if(!['MANDATORY','ELECTIVE'].includes(type)){setError('Loại học phần không hợp lệ');return}const knowledgeGroupCode=window.prompt('Mã nhóm kiến thức:',course.knowledgeGroupCode||'')||null;const prerequisiteCourseCodes=(window.prompt('Mã tiên quyết, phân cách dấu phẩy:',(course.prerequisiteCourseCodes||[]).join(', '))||'').split(',').map(x=>x.trim()).filter(Boolean);const specializationCodes=(window.prompt('Mã định hướng, phân cách dấu phẩy:',(course.specializationCodes||[]).join(', '))||'').split(',').map(x=>x.trim()).filter(Boolean);try{await request(`/api/curriculums/${detail.id}/courses/${encodeURIComponent(course.courseCode)}`,{token,method:'PUT',body:{semesterNumber:sem,type,knowledgeGroupCode,specializationCodes,prerequisiteCourseCodes}});await refreshDetail();notify('Đã cập nhật học phần trong CTĐT')}catch(e){setError(e.message)}}
 const filtered=items.filter(x=>JSON.stringify(x).toLowerCase().includes(search.toLowerCase()));
 if(kind==='changes')return <><div className="toolbar"><label className="field-label inline-field">Loại thực thể<select value={form.entityType||''} onChange={e=>setForm({...form,entityType:e.target.value})}><option value="">Tất cả</option><option value="Curriculum">Chương trình đào tạo</option><option value="Course">Học phần</option></select></label><button className="primary" onClick={load} disabled={loading}>{loading?'Đang tải...':'Lọc lịch sử'}</button></div>{error&&<div className="alert">{error}</div>}<div className="panel table-panel"><div className="panel-head"><div><h3>Lịch sử kiểm toán</h3><p>Thông tin thao tác được ghi nhận từ các API quản lý CTĐT và học phần.</p></div><span className="neutral-chip">{items.length} bản ghi</span></div>{items.length?<div className="table-wrap"><table><thead><tr><th>Thời gian</th><th>Thực thể</th><th>ID</th><th>Thao tác</th><th>Chi tiết thay đổi</th><th>Người thực hiện</th></tr></thead><tbody>{items.map(x=><tr key={x.id}><td>{dateText(x.createdAt)}</td><td>{x.entityType}</td><td className="code-cell">{x.entityId}</td><td><Status value={x.action}/></td><td>{(x.changes||[]).map(c=><div className="change-item" key={c.field}><b>{c.field}</b>: {String(c.oldValue??'—')} → {String(c.newValue??'—')}</div>)}</td><td>{x.changedBy||'—'}</td></tr>)}</tbody></table></div>:<Empty title="Chưa có lịch sử thay đổi" text="Lịch sử sẽ xuất hiện sau khi dữ liệu CTĐT hoặc học phần được tạo/cập nhật."/>}</div></>;
 return <><div className="toolbar"><SearchBar value={search} onChange={setSearch} placeholder={`Tìm kiếm ${kind==='majors'?'mã hoặc tên ngành':kind==='courses'?'mã hoặc tên học phần':'mã hoặc tên CTĐT'}...`}/><button className="primary" onClick={load} disabled={loading}>{loading?'Đang tải...':'Tìm kiếm'}</button><button className="primary" onClick={openCreate}><Plus size={16}/> {kind==='majors'?'Thêm ngành':kind==='courses'?'Thêm học phần':'Tạo CTĐT'}</button></div>{error&&<div className="alert">{error}</div>}{detail&&<section className="panel catalog-detail"><div className="panel-head"><div><span className="eyebrow">CHI TIẾT DỮ LIỆU</span><h3>{detail.curriculumName||detail.courseName||detail.name}</h3><p>{detail.curriculumCode||detail.courseCode||detail.code} · {detail.status}</p></div><button className="outline" onClick={()=>setDetail(null)}>Đóng</button></div>{kind==='curriculums'&&<><div className="structure-actions"><button className="outline" onClick={addKnowledgeGroup}><Plus size={15}/> Thêm nhóm kiến thức</button><button className="outline" onClick={addSpecialization}><Plus size={15}/> Thêm định hướng</button><button className="primary" onClick={addCurriculumCourse}><Plus size={15}/> Thêm học phần vào CTĐT</button></div><h4>Nhóm kiến thức</h4>{(detail.knowledgeGroups||[]).length?<div className="structure-list">{detail.knowledgeGroups.map(g=><div className="structure-item" key={g.groupCode}><span><b>{g.groupCode}</b> · {g.groupName} <small>Thứ tự {g.order??'—'}</small></span><div className="row-actions"><button className="text-btn" onClick={()=>editKnowledgeGroup(g)}>Sửa</button><button className="text-btn danger-text" onClick={()=>removeKnowledgeGroup(g)}>Xóa</button></div></div>)}</div>:<p className="muted">Chưa cấu hình nhóm kiến thức.</p>}<h4>Chuyên ngành / định hướng</h4><div className="structure-list">{(detail.specializations||[]).map(sp=><div className="structure-item" key={sp.code}><span><b>{sp.code}</b> · {sp.name}</span><button className="text-btn danger-text" onClick={()=>removeSpecialization(sp)}>Xóa</button></div>)}{!(detail.specializations||[]).length&&<span className="muted">Chưa cấu hình định hướng.</span>}</div>{(detail.semesters||[]).map(s=><div className="catalog-semester" key={s.semesterNumber}><div className="panel-head"><b>Học kỳ {s.semesterNumber}</b><span className="muted">{(s.courses||[]).length} học phần</span></div>{(s.courses||[]).length?<div className="table-wrap"><table><thead><tr><th>Mã môn</th><th>Tên học phần</th><th>Loại</th><th>Nhóm KT</th><th>Tiên quyết</th><th>Thao tác</th></tr></thead><tbody>{s.courses.map(c=><tr key={c.courseCode}><td className="code-cell">{c.courseCode}</td><td>{c.courseName||'—'}</td><td>{c.type}</td><td>{c.knowledgeGroupCode||'—'}</td><td>{(c.prerequisiteCourseCodes||[]).join(', ')||'—'}</td><td><div className="row-actions"><button className="text-btn" onClick={()=>editCurriculumCourse(c,s.semesterNumber)}>Sửa</button><button className="text-btn danger-text" onClick={()=>removeCurriculumCourse(c.courseCode)}>Xóa</button></div></td></tr>)}</tbody></table></div>:<p className="muted">Chưa có học phần trong học kỳ này.</p>}</div>)}</>}{kind==='courses'&&<p>{detail.description||'Không có mô tả.'} · {detail.credits} tín chỉ · {detail.department||'Chưa phân khoa'}</p>}{kind==='majors'&&<p>{detail.description||'Không có mô tả.'}</p>}</section>}
 <div className="panel table-panel"><div className="panel-head"><div><h3>{config.title}</h3><p>{kind==='majors'?'Tạo, cập nhật và ngừng áp dụng ngành đào tạo.':kind==='courses'?'Quản lý danh mục học phần dùng chung.':'Tạo, sao chép, chỉnh sửa và lưu trữ các phiên bản CTĐT.'}</p></div><span className="neutral-chip">{filtered.length} bản ghi</span></div>{filtered.length?<div className="table-wrap"><table><thead><tr>{(kind==='majors'?['Mã ngành','Tên ngành','Trạng thái','']:kind==='courses'?['Mã học phần','Tên học phần','Tín chỉ','Khoa','Trạng thái','']:['Mã CTĐT','Tên chương trình','Khóa','Năm áp dụng','Phiên bản','Trạng thái','']).map((h,i)=><th key={i}>{h}</th>)}</tr></thead><tbody>{filtered.map(item=><tr key={item.id}>{kind==='majors'?<><td className="code-cell">{item.code}</td><td><b>{item.name}</b></td><td><Status value={item.status}/></td></>:kind==='courses'?<><td className="code-cell">{item.courseCode}</td><td><b>{item.courseName}</b></td><td>{item.credits}</td><td>{item.department||'—'}</td><td><Status value={item.status}/></td></>:<><td className="code-cell">{item.curriculumCode}</td><td><b>{item.curriculumName}</b></td><td>{item.cohort}</td><td>{item.appliedYear}</td><td>{item.version||1}</td><td><Status value={item.status}/></td></>}<td><div className="row-actions"><button className="text-btn" onClick={()=>showDetail(item)}>Chi tiết</button><button className="text-btn" onClick={()=>openEdit(item)}>Sửa</button>{kind==='curriculums'&&<button className="text-btn" onClick={()=>clone(item)}>Clone</button>}<button className="text-btn danger-text" onClick={()=>remove(item)}>{kind==='curriculums'?'Lưu trữ':'Ngừng'}</button></div></td></tr>)}</tbody></table></div>:<Empty title="Chưa có dữ liệu" text="Tạo bản ghi mới hoặc thử thay đổi từ khóa tìm kiếm."/>}</div>
 {modal&&<Modal title={`${editing?'Cập nhật':'Tạo'} ${kind==='majors'?'ngành đào tạo':kind==='courses'?'học phần':'chương trình đào tạo'}`} onClose={()=>setModal(false)} onSubmit={save} busy={loading}>{error&&<div className="alert">{error}</div>}<div className="form-grid">{kind==='majors'?<><Field label="Mã ngành" value={editing?.code||form.code||''} set={v=>setForm({...form,code:v})} disabled={!!editing}/>{!editing&&<Field label="Tên ngành" value={form.name||''} set={v=>setForm({...form,name:v})} required/>}{editing&&<Field label="Tên ngành" value={form.name||''} set={v=>setForm({...form,name:v})} required/>}<Field label="Trạng thái" value={form.status||'ACTIVE'} set={v=>setForm({...form,status:v})}/><label className="field-label full-field">Mô tả<textarea value={form.description||''} onChange={e=>setForm({...form,description:e.target.value})}/></label></>:kind==='courses'?<>{!editing&&<Field label="Mã học phần" value={form.courseCode||''} set={v=>setForm({...form,courseCode:v})} required/>}<Field label="Tên học phần" value={form.courseName||''} set={v=>setForm({...form,courseName:v})} required/><Field label="Số tín chỉ" type="number" min="1" value={form.credits??3} set={v=>setForm({...form,credits:v})} required/><Field label="Giờ lý thuyết" type="number" min="0" value={form.theoryHours??0} set={v=>setForm({...form,theoryHours:v})} required/><Field label="Giờ thực hành" type="number" min="0" value={form.practiceHours??0} set={v=>setForm({...form,practiceHours:v})} required/><Field label="Khoa/Bộ môn" value={form.department||''} set={v=>setForm({...form,department:v})}/><Field label="Trạng thái" value={form.status||'ACTIVE'} set={v=>setForm({...form,status:v})}/><label className="field-label full-field">Mô tả<textarea value={form.description||''} onChange={e=>setForm({...form,description:e.target.value})}/></label></>:<><Field label="Mã CTĐT" value={editing?.curriculumCode||form.curriculumCode||''} set={v=>setForm({...form,curriculumCode:v})} required disabled={!!editing}/><Field label="Tên CTĐT" value={form.curriculumName||''} set={v=>setForm({...form,curriculumName:v})} required/><label className="field-label">Ngành đào tạo<select value={form.majorId||''} onChange={e=>setForm({...form,majorId:e.target.value})} required><option value="">Chọn ngành</option>{majors.map(m=><option key={m.id} value={m.id}>{m.code} · {m.name}</option>)}</select></label><Field label="Khóa tuyển sinh" value={form.cohort||''} set={v=>setForm({...form,cohort:v})} required/><Field label="Năm áp dụng" type="number" min="2000" value={form.appliedYear||new Date().getFullYear()} set={v=>setForm({...form,appliedYear:v})} required/><label className="field-label">Trạng thái<select value={form.status||'DRAFT'} onChange={e=>setForm({...form,status:e.target.value})}><option value="DRAFT">DRAFT</option><option value="ACTIVE">ACTIVE</option><option value="ARCHIVED">ARCHIVED</option></select></label><label className="field-label">Thời điểm chọn định hướng<select value={form.specializationSelectionTiming||'LATER'} onChange={e=>setForm({...form,specializationSelectionTiming:e.target.value})}><option value="EARLY">EARLY</option><option value="LATER">LATER</option></select></label>{form.specializationSelectionTiming!=='EARLY'&&<Field label="Học kỳ chọn định hướng" type="number" min="1" max="12" value={form.specializationSelectionSemester??5} set={v=>setForm({...form,specializationSelectionSemester:v})}/>}<label className="field-label full-field">Mô tả<textarea value={form.description||''} onChange={e=>setForm({...form,description:e.target.value})}/></label>{editing&&<p className="field-hint full-field">Các nhóm kiến thức, học phần và học kỳ hiện có sẽ được giữ nguyên khi chỉ cập nhật thông tin cơ bản.</p>}</>}</div></Modal>}</>
}

createRoot(document.getElementById('root')).render(<App/>);
